def gen(rng):
    def lsum(s):
        total = 0
        for i, ch in enumerate(reversed(s)):
            d = int(ch)
            if i % 2 == 1:
                d *= 2
                if d > 9:
                    d -= 9
            total += d
        return total

    def make_valid(prefix):
        for c in '0123456789':
            if lsum(prefix + c) % 10 == 0:
                return prefix + c

    def rnd(L):
        return ''.join(rng.choice('0123456789') for _ in range(L))

    def fmt(xs):
        return str(len(xs)) + '\n' + '\n'.join(xs)

    tests = [fmt(['0']), fmt(['5']), fmt(['00', '18', '81', '1234']), fmt(['4111111111111111', '4111111111111112', '0000000000000000'])]
    for _ in range(6):
        xs = []
        for _ in range(rng.randint(1, 12)):
            L = rng.randint(1, 19)
            if rng.random() < 0.5:
                xs.append(make_valid(rnd(L - 1)))
            else:
                xs.append(rnd(L))
        tests.append(fmt(xs))
    tests.append(fmt([rnd(rng.randint(1, 3)) for _ in range(20)]))
    big = []
    for _ in range(100000):
        L = rng.randint(12, 19)
        big.append(make_valid(rnd(L - 1)) if rng.random() < 0.5 else rnd(L))
    tests.append(fmt(big))
    big2 = []
    for _ in range(100000):
        big2.append(make_valid(rnd(18)) if rng.random() < 0.3 else rnd(19))
    tests.append(fmt(big2))
    tests.append(fmt(['9' * 19] * 100000))
    return tests

